function useBreakpoint() {
  const [w,setW]=useState(window.innerWidth);
  useEffect(()=>{const fn=()=>setW(window.innerWidth);window.addEventListener("resize",fn);return()=>window.removeEventListener("resize",fn);},[]);
  return {isMobile:w<640,isTablet:w>=640&&w<1024,isDesktop:w>=1024};
}

function genId() { return Date.now().toString(36) + Math.random().toString(36).slice(2); }

function isFriOrSat(dateStr) {
  if(!dateStr) return false;
  const d=new Date(dateStr+"T12:00:00"); return d.getDay()===5||d.getDay()===6;
}

function driveToDirectUrl(url) {
  if(!url) return null;
  const m=url.match(/\/d\/([a-zA-Z0-9_-]+)/)||url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m?`https://drive.google.com/uc?export=download&id=${m[1]}`:url;
}
function driveToViewUrl(url) {
  if(!url) return null;
  const m=url.match(/\/d\/([a-zA-Z0-9_-]+)/);
  return m?`https://drive.google.com/file/d/${m[1]}/view`:url;
}
function driveToEmbedUrl(url) {
  if(!url) return null;
  const m=url.match(/\/d\/([a-zA-Z0-9_-]+)/)||url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m?`https://drive.google.com/file/d/${m[1]}/preview`:url;
}

function playDingSound() {
  try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[[880,660,0,0.6],[1320,990,0.05,0.3]].forEach(([f1,f2,d,v])=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.setValueAtTime(f1,ctx.currentTime+d);o.frequency.exponentialRampToValueAtTime(f2,ctx.currentTime+d+0.3);g.gain.setValueAtTime(v,ctx.currentTime+d);g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+d+1.2);o.start(ctx.currentTime+d);o.stop(ctx.currentTime+d+1.3);});}catch(e){}
}
function playChime() {
  try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[523,659,784,1047].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type="sine";o.frequency.value=f;g.gain.setValueAtTime(0,ctx.currentTime+i*0.12);g.gain.linearRampToValueAtTime(0.35,ctx.currentTime+i*0.12+0.05);g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+i*0.12+0.8);o.start(ctx.currentTime+i*0.12);o.stop(ctx.currentTime+i*0.12+0.9);});}catch(e){}
}

