function InlineEdit({value,onSave,style={},placeholder="Edit..."}) {
  const [editing,setEditing]=useState(false);const [draft,setDraft]=useState(value);const ref=useRef(null);
  useEffect(()=>{if(editing)ref.current?.focus();},[editing]);useEffect(()=>{setDraft(value);},[value]);
  function commit(){setEditing(false);if(draft.trim()&&draft.trim()!==value)onSave(draft.trim());else setDraft(value);}
  if(editing) return <input ref={ref} value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==="Enter")commit();if(e.key==="Escape"){setDraft(value);setEditing(false);}}} style={{...style,border:`1.5px solid ${C.blue}`,borderRadius:6,padding:"2px 8px",outline:"none",fontFamily:"Raleway,sans-serif",background:"white",minWidth:120}} placeholder={placeholder}/>;
  return <span onClick={()=>setEditing(true)} title="Click to edit" style={{...style,cursor:"text",borderBottom:`1.5px dashed ${C.blue}55`,paddingBottom:1}}>{value}</span>;
}

